```cpp
template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    int n2 = hidden_size / 2;
    const half2* x_h2 = reinterpret_cast<const half2*>(input + row * hidden_size);
    const half2* w_h2 = reinterpret_cast<const half2*>(weight);
    half2* o_h2 = reinterpret_cast<half2*>(output + row * hidden_size);

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < n2; i += blockDim.x) {
        half2 xv = __ldg(&x_h2[i]);
        float v0 = __half2float(xv.x);
        float v1 = __half2float(xv.y);
        sum_sq += v0 * v0 + v1 * v1;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[16]; // max 16 warps for 512 threads
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    for (int i = threadIdx.x; i < n2; i += blockDim.x) {
        half2 xv = __ldg(&x_h2[i]);
        half2 wv = __ldg(&w_h2[i]);
        half2 result;
        result.x = __float2half(__half2float(xv.x) * rms_inv * __half2float(wv.x));
        result.y = __float2half(__half2float(xv.y) * rms_inv * __half2float(wv.y));
        o_h2[i] = result;
    }
}
```

